"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def FIRST_NON_REPEATING_CHARACTER(s):
    char_count = {}
    for c in s:
        if (c in char_count):
            char_count[c] = (char_count[c] + 1)
        else:
            char_count[c] = 1
    for c in s:
        if (char_count[c] == 1):
            return c
    return None
